// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CopyIcon } from 'lucide-react'

import { DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, CASES, INPUT, SEQUENCE } from './script'

const LAYERS = [
  { id: 'raw', value: INPUT },
  ...CASES.filter((item) => (SEQUENCE as readonly string[]).includes(item.id)),
]

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  const swap = (from: string, to: string) => {
    tl.to(qa(`ch-${from}`), {
      rotateX: 90,
      opacity: 0,
      duration: 0.22,
      stagger: 0.012,
      ease: 'power2.in',
    })
    tl.fromTo(
      qa(`ch-${to}`),
      { rotateX: -90, opacity: 0 },
      { rotateX: 0, opacity: 1, duration: 0.45, stagger: 0.018, ease: 'back.out(2.2)' },
      '<0.18',
    )
  }
  const press = (id: string) => {
    move(`case-${id}`)
    click(`case-${id}`)
    tl.to(
      qa('case'),
      { backgroundColor: 'rgba(255,255,255,0.03)', color: '#8b8b9a', duration: 0.15 },
      '<',
    )
    tl.to(
      q(`case-${id}`),
      { backgroundColor: 'rgba(129,140,248,0.2)', color: '#f4f4f6', duration: 0.15 },
      '<',
    )
  }

  step(0)
  move('input', { at: 0.3, ax: 0.15 })
  click('input')
  type('input-text', INPUT, { speed: 0.05 })
  tl.fromTo(
    qa('ch-raw'),
    { rotateX: -90, opacity: 0 },
    { rotateX: 0, opacity: 1, duration: 0.4, stagger: 0.012 },
    '-=0.3',
  )

  let previous = 'raw'
  SEQUENCE.forEach((id, index) => {
    step(index + 1, '+=0.5')
    press(id)
    swap(previous, id)
    previous = id
  })
  move('copy', { at: '+=0.3' })
  click('copy')
  tl.fromTo(q('copied'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.6)
  tl.to([q('copied'), ...qa(`ch-${previous}`)], { opacity: 0, duration: 0.3 })
}

export default function Demo() {
  return (
    <DemoStage
      label="Case Converter flipping a phrase into camelCase, snake_case and CONSTANT_CASE"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-3">
          <div
            data-d="input"
            className="flex h-9 items-center rounded-lg border border-line bg-canvas/80 px-3 text-[12px]"
          >
            <span data-d="input-text" className="demo-caret text-ink-soft" />
          </div>
          <div className="relative flex h-24 items-center justify-center overflow-hidden rounded-xl border border-line-strong bg-[radial-gradient(120%_120%_at_50%_0%,rgb(129_140_248/0.16),transparent_60%)] [perspective:600px]">
            {LAYERS.map((layer) => (
              <p
                key={layer.id}
                className="absolute whitespace-pre font-mono text-[21px] font-medium tracking-tight"
              >
                {layer.value.split('').map((char, index) => (
                  <span
                    key={index}
                    data-d={`ch-${layer.id}`}
                    className="inline-block opacity-0 [transform-origin:50%_50%_-10px]"
                  >
                    {char === ' ' ? '\u00a0' : char}
                  </span>
                ))}
              </p>
            ))}
            <span
              data-d="copy"
              className="absolute bottom-2 right-2 flex size-6 items-center justify-center rounded-md border border-line-strong bg-canvas/80 text-muted"
            >
              <CopyIcon className="size-3" />
            </span>
            <span
              data-d="copied"
              className="absolute bottom-2.5 right-10 rounded-full bg-emerald px-2 py-0.5 text-[9.5px] font-medium text-canvas opacity-0"
            >
              Ready
            </span>
          </div>
          <Label>Convert to</Label>
          <div className="grid grid-cols-3 gap-1.5">
            {CASES.map((item) => (
              <span
                key={item.id}
                data-d={`case case-${item.id}`}
                className="flex h-8 items-center justify-center rounded-lg border border-line bg-white/[0.03] font-mono text-[10.5px] text-muted"
              >
                {item.label}
              </span>
            ))}
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
